package com.codearena;

import com.codearena.dao.*;
import com.codearena.model.*;
import com.codearena.service.QuizService;
import com.codearena.util.Database;
import com.sun.net.httpserver.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.sql.SQLException;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class App {
    private static final UserDao users = new UserDao(); private static final LearningDao learning = new LearningDao(); private static final ResultDao results = new ResultDao(); private static final QuizService quizzes = new QuizService();
    private static final Map<String, User> sessions = new ConcurrentHashMap<>();
    public static void main(String[] args) throws IOException { Database.initialise(); HttpServer server = HttpServer.create(new java.net.InetSocketAddress(8080), 0); server.createContext("/", App::route); server.setExecutor(null); server.start(); System.out.println("CodeArena started at http://localhost:8080"); }
    private static void route(HttpExchange exchange) throws IOException {
        try { String path = exchange.getRequestURI().getPath();
            if (path.startsWith("/static/")) { staticFile(exchange, path); return; }
            if ("/".equals(path)) home(exchange); else if ("/register".equals(path)) register(exchange); else if ("/login".equals(path)) login(exchange);
            else if ("/logout".equals(path)) { sessions.remove(cookie(exchange, "session")); redirect(exchange, "/"); }
            else if ("/dashboard".equals(path)) dashboard(exchange); else if ("/topic".equals(path)) topic(exchange); else if ("/quiz".equals(path)) quiz(exchange);
            else if ("/history".equals(path)) history(exchange); else if ("/admin".equals(path)) admin(exchange); else if ("/admin/delete".equals(path)) deleteQuestion(exchange); else response(exchange, 404, page("Not found", "<h1>Page not found</h1><p><a href='/'>Return home</a></p>"));
        } catch (SQLException | IllegalArgumentException exception) { response(exchange, 400, page("Something went wrong", "<h1>We could not complete that request</h1><p>" + esc(exception.getMessage()) + "</p><p><a href='/'>Return home</a></p>")); }
    }
    private static void home(HttpExchange x) throws IOException { response(x, 200, page("CodeArena", "<section class='hero'><p class='eyebrow'>JAVA + DBMS PRACTICE</p><h1>Build confidence, one topic at a time.</h1><p>Short notes, focused quizzes, and a record of your progress.</p><a class='button' href='/register'>Create student account</a> <a class='link-button' href='/login'>Log in</a></section><section class='features'><article><h2>Learn</h2><p>Read concise notes before trying a topic.</p></article><article><h2>Practise</h2><p>Answer multiple-choice questions with instant feedback.</p></article><article><h2>Review</h2><p>See previous quiz attempts and scores.</p></article></section>")); }
    private static void register(HttpExchange x) throws IOException, SQLException { if ("GET".equals(x.getRequestMethod())) { response(x, 200, formPage("Create your account", "<form method='post' data-validate><label>Name<input name='name' required maxlength='80'></label><label>Email<input name='email' type='email' required></label><label>Password<input name='password' type='password' required minlength='6'></label><button>Create account</button></form>")); return; } Map<String,String> p = form(x); if (p.getOrDefault("name", "").isBlank() || p.getOrDefault("password", "").length() < 6) throw new IllegalArgumentException("Enter a name and a password of at least six characters."); try { users.register(p.get("name"), p.get("email"), p.get("password")); redirect(x, "/login?new=1"); } catch (SQLException e) { if (e.getMessage().toLowerCase().contains("unique")) throw new IllegalArgumentException("That email address already has an account."); throw e; } }
    private static void login(HttpExchange x) throws IOException, SQLException { if ("GET".equals(x.getRequestMethod())) { String message = x.getRequestURI().getQuery() != null ? "<p class='notice'>Account created. Please log in.</p>" : ""; response(x, 200, formPage("Welcome back", message + "<form method='post' data-validate><label>Email<input name='email' type='email' required></label><label>Password<input name='password' type='password' required></label><button>Log in</button></form><p>Admin demo: admin@codearena.local / Admin@123</p>")); return; } Map<String,String> p = form(x); User user = users.authenticate(p.getOrDefault("email", ""), p.getOrDefault("password", "")); if (user == null) throw new IllegalArgumentException("Email or password is incorrect."); String token = UUID.randomUUID().toString(); sessions.put(token, user); x.getResponseHeaders().add("Set-Cookie", "session=" + token + "; HttpOnly; SameSite=Lax; Path=/"); redirect(x, user.isAdmin() ? "/admin" : "/dashboard"); }
    private static void dashboard(HttpExchange x) throws IOException, SQLException { User user = student(x); ResultDao.Progress progress=results.progress(user.getId()); StringBuilder cards = new StringBuilder(); for (Subject subject : learning.subjects()) { cards.append("<article class='card subject-card'><p class='eyebrow'>").append(esc(subject.name())).append("</p><h2>").append(esc(subject.description())).append("</h2>"); for (Topic topic : learning.topics(subject.id())) cards.append("<a class='topic-link' data-topic href='/topic?id=").append(topic.id()).append("'>").append(esc(topic.name())).append("<span>Read notes and quiz →</span></a>"); cards.append("</article>"); } String stats="<section class='stats'><article><strong>"+progress.attempts()+"</strong><span>Quiz attempts</span></article><article><strong>"+progress.bestPercentage()+"%</strong><span>Best score</span></article><article><strong>"+progress.averagePercentage()+"%</strong><span>Average score</span></article></section>"; response(x, 200, page("Dashboard", "<p class='eyebrow'>HELLO, " + esc(user.getName().toUpperCase()) + "</p><h1>Your learning dashboard</h1><p>Search a topic, revise the notes, then test yourself.</p>"+stats+"<label class='search-label'>Find a topic<input id='topic-search' placeholder='Try Java, SQL, joins...'></label><div class='cards' id='topic-cards'>" + cards + "</div>")); }
    private static void topic(HttpExchange x) throws IOException, SQLException { student(x); Topic topic = learning.topic(number(x, "id")); if (topic == null) throw new IllegalArgumentException("Topic was not found."); response(x, 200, page(topic.name(), "<a class='back' href='/dashboard'>← All topics</a><h1>" + esc(topic.name()) + "</h1><p class='lead'>" + esc(topic.description()) + "</p><article class='note'>" + paragraph(topic.material()) + "</article><a class='button' href='/quiz?id=" + topic.id() + "'>Start quiz</a>")); }
    private static void quiz(HttpExchange x) throws IOException, SQLException { User user = student(x); int topicId = number(x, "id"); List<Question> questions = learning.questions(topicId); if (questions.isEmpty()) throw new IllegalArgumentException("There are no quiz questions for this topic yet."); if ("GET".equals(x.getRequestMethod())) { StringBuilder body = new StringBuilder("<a class='back' href='/topic?id=").append(topicId).append("'>← Back to notes</a><h1>Topic quiz</h1><form method='post' class='quiz'>"); for (int i=0;i<questions.size();i++) { Question q=questions.get(i); body.append("<fieldset><legend>").append(i+1).append(". ").append(esc(q.text())).append("</legend>"); for (Option o:q.options()) body.append("<label class='option'><input type='radio' name='q_").append(q.id()).append("' value='").append(o.label()).append("'> <b>").append(o.label()).append(".</b> ").append(esc(o.text())).append("</label>"); body.append("</fieldset>"); } body.append("<button>Submit answers</button></form>"); response(x,200,page("Quiz",body.toString())); return; } Map<String,String> p=form(x); Map<Integer,String> submitted=new HashMap<>(); for(Question q:questions) submitted.put(q.id(),p.getOrDefault("q_"+q.id(),"")); QuizService.QuizOutcome outcome=quizzes.markAndSave(user.getId(),topicId,questions,submitted); StringBuilder review=new StringBuilder(); for(Question q:questions) { String answer=submitted.get(q.id()); boolean ok=q.correctAnswer().equalsIgnoreCase(answer); review.append("<li class='").append(ok?"correct":"wrong").append("'><b>").append(esc(q.text())).append("</b><br>Your answer: ").append(answer.isBlank()?"Not answered":esc(answer)).append(" | Correct: ").append(esc(q.correctAnswer())).append("<br><small>").append(esc(q.explanation())).append("</small></li>"); } response(x,200,page("Your result","<h1>"+outcome.score()+" / "+outcome.total()+"</h1><p class='lead'>You scored "+outcome.percentage()+"%.</p><ul class='review'>"+review+"</ul><a class='button' href='/history'>View history</a>")); }
    private static void history(HttpExchange x) throws IOException, SQLException { User user=student(x); response(x,200,page("History",resultTable(results.history(user.getId()), false))); }
    private static void admin(HttpExchange x) throws IOException, SQLException { adminUser(x); if ("POST".equals(x.getRequestMethod())) { Map<String,String> p=form(x); Map<String,String> choices=Map.of("A",p.get("option_a"),"B",p.get("option_b"),"C",p.get("option_c"),"D",p.get("option_d")); if(choices.values().stream().anyMatch(v->v==null||v.isBlank())) throw new IllegalArgumentException("Add all four answer options."); learning.addQuestion(Integer.parseInt(p.get("topic")),p.get("text"),p.get("correct"),p.getOrDefault("explanation", ""),choices); redirect(x,"/admin"); return; } StringBuilder topicOptions=new StringBuilder(); for(Subject subject:learning.subjects()) for(Topic topic:learning.topics(subject.id())) topicOptions.append("<option value='").append(topic.id()).append("'>").append(esc(subject.name())).append(" - ").append(esc(topic.name())).append("</option>"); StringBuilder managed=new StringBuilder(); for(Question q:learning.allQuestions()) managed.append("<li><b>#").append(q.id()).append("</b> ").append(esc(q.text())).append(" <span class='pill'>Answer ").append(esc(q.correctAnswer())).append("</span> <a class='delete-link' href='/admin/delete?id=").append(q.id()).append("' onclick=\"return confirm('Delete this question?')\">Delete</a></li>"); String form="<h1>Admin dashboard</h1><p>Manage quiz questions and review student performance.</p>"+resultTable(results.history(null),true)+"<h2>Add complete MCQ</h2><form method='post' class='admin-form'><label>Topic<select name='topic'>"+topicOptions+"</select></label><label>Question<input name='text' required maxlength='500'></label><div class='option-grid'><label>A<input name='option_a' required></label><label>B<input name='option_b' required></label><label>C<input name='option_c' required></label><label>D<input name='option_d' required></label></div><label>Correct option<select name='correct'><option>A</option><option>B</option><option>C</option><option>D</option></select></label><label>Explanation<textarea name='explanation'></textarea></label><button>Add question</button></form><h2>Question bank</h2><ul class='question-bank'>"+managed+"</ul>"; response(x,200,page("Admin",form)); }
    private static void deleteQuestion(HttpExchange x) throws IOException, SQLException { adminUser(x); learning.deleteQuestion(number(x,"id")); redirect(x,"/admin"); }
    private static String resultTable(List<Result> data, boolean includeStudent) { StringBuilder rows=new StringBuilder(); DateTimeFormatter f=DateTimeFormatter.ofPattern("dd MMM yyyy HH:mm"); for(Result r:data) rows.append("<tr>").append(includeStudent?"<td>"+esc(r.student())+"</td>":"").append("<td>").append(esc(r.subject())).append("</td><td>").append(esc(r.topic())).append("</td><td>").append(r.score()).append("/").append(r.totalMarks()).append("</td><td>").append(r.percentage()).append("%</td><td>").append(r.attemptedAt().format(f)).append("</td></tr>"); return "<h1>"+(includeStudent?"Student results":"Your previous attempts")+"</h1><table><thead><tr>"+(includeStudent?"<th>Student</th>":"")+"<th>Subject</th><th>Topic</th><th>Score</th><th>Percentage</th><th>Date</th></tr></thead><tbody>"+(rows.isEmpty()?"<tr><td colspan='6'>No attempts yet.</td></tr>":rows)+"</tbody></table>"; }
    private static User student(HttpExchange x) throws IOException { User u=current(x); if(u==null){redirect(x,"/login");throw new IllegalArgumentException("Please log in first.");} if(u.isAdmin()){redirect(x,"/admin");throw new IllegalArgumentException("Student page only.");} return u; }
    private static User adminUser(HttpExchange x) throws IOException { User u=current(x); if(u==null||!u.isAdmin()){redirect(x,"/login");throw new IllegalArgumentException("Administrator access is required.");} return u; }
    private static User current(HttpExchange x) { return sessions.get(cookie(x,"session")); }
    private static void staticFile(HttpExchange x,String path) throws IOException { if(!"/static/style.css".equals(path)||App.class.getResourceAsStream(path)==null){response(x,404,"Not found");return;} x.getResponseHeaders().set("Content-Type","text/css; charset=utf-8"); byte[] b=App.class.getResourceAsStream(path).readAllBytes();x.sendResponseHeaders(200,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);} }
    private static Map<String,String> form(HttpExchange x) throws IOException { return parse(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8)); }
    private static Map<String,String> parse(String value) throws UnsupportedEncodingException { Map<String,String> result=new HashMap<>(); for(String pair:value.split("&")){if(pair.isEmpty())continue;String[] p=pair.split("=",2);result.put(URLDecoder.decode(p[0],"UTF-8"),p.length>1?URLDecoder.decode(p[1],"UTF-8"):"");}return result; }
    private static int number(HttpExchange x,String name) throws UnsupportedEncodingException { String q=x.getRequestURI().getRawQuery(); String v=parse(q==null?"":q).get(name); return Integer.parseInt(v); }
    private static String cookie(HttpExchange x,String name){for(String h:x.getRequestHeaders().getOrDefault("Cookie",List.of()))for(String p:h.split(";")){String[] kv=p.trim().split("=",2);if(kv.length==2&&kv[0].equals(name))return kv[1];}return "";}
    private static void redirect(HttpExchange x,String target)throws IOException{x.getResponseHeaders().set("Location",target);x.sendResponseHeaders(303,-1);}
    private static void response(HttpExchange x,int code,String body)throws IOException{byte[] b=body.getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","text/html; charset=utf-8");x.sendResponseHeaders(code,b.length);try(OutputStream o=x.getResponseBody()){o.write(b);}}
    private static String formPage(String title,String form){return page(title,"<main class='form-wrap'><h1>"+esc(title)+"</h1>"+form+"</main>");}
    private static String page(String title,String content){User noUser=null;return "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>"+esc(title)+" | CodeArena</title><link rel='stylesheet' href='/static/style.css'></head><body><header><a class='brand' href='/'>CodeArena<span>.</span></a><nav><a href='/dashboard'>Dashboard</a><a href='/history'>History</a><a href='/logout'>Log out</a></nav></header><main>"+content+"</main><footer>CodeArena - Java OOP and DBMS/SQL practice</footer><script src='/static/app.js'></script></body></html>";}
    private static String paragraph(String text){return esc(text).replace("\n","<br>");}
    private static String esc(String value){if(value==null)return "";return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
}
